<?php
require __DIR__.'/../vendor/autoload.php';$app=require __DIR__.'/../bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\DB;use Illuminate\Http\Request;
function check($ok,$m){if(!$ok)throw new RuntimeException($m);echo "PASS: $m\n";}
DB::beginTransaction();try{
$tag='catalog-audit-'.bin2hex(random_bytes(5));$admin=App\Models\User::forceCreate(['name'=>'Catalog Admin','email'=>$tag.'@example.test','password'=>bin2hex(random_bytes(16)),'is_admin'=>true,'is_super_admin'=>true]);
function req($path,$data=[]){global $app,$admin;$r=Request::create($path,'POST',$data);$app->instance('request',$r);$r->setUserResolver(fn()=>$admin);$r->setLaravelSession($app->make('session.store'));return $r;}
$attributes=[];$attributesController=new App\Http\Controllers\CatalogAttributeController;foreach(['brands','colors','sizes'] as $type){$data=['name'=>$tag.' '.$type,'is_active'=>true];if($type==='colors')$data['color']='#123456';$attributesController->store(req('/admin/'.$type,$data),$type);$attributes[$type]=App\Models\CatalogAttribute::where('name',$data['name'])->firstOrFail();}check(count($attributes)===3,'Admin creates brand, color and size');
$category=App\Models\Category::create(['name'=>$tag,'slug'=>$tag,'serial'=>999,'is_active'=>true]);$data=['name'=>$tag.' product','category_id'=>$category->id,'brand_id'=>$attributes['brands']->id,'regular_price'=>100,'sale_price'=>80,'stock'=>4,'new_arrival'=>true,'status'=>true,'description'=>'<p>Valid content</p><script>alert(1)</script>','variants'=>[['color_id'=>$attributes['colors']->id,'size_id'=>$attributes['sizes']->id,'stock'=>3,'price'=>90]]];
$controller=new App\Http\Controllers\ProductController;$library=$app->make(App\Services\MediaLibrary::class);$controller->save(req('/admin/products',$data),$library);$product=App\Models\Product::where('name',$data['name'])->firstOrFail();check($product->variants()->count()===1 && !str_contains($product->description,'<script'),'Admin product entry saves variants and removes unsafe HTML');
$r=req('/categories/'.$category->slug);$response=(new App\Http\Controllers\PublicStorefrontController)->category($r,$category->slug);$props=(new ReflectionProperty($response,'props'))->getValue($response);foreach(['brands','colors','sizes'] as $type)check($props['filterOptions'][$type]->pluck('id')->contains($attributes[$type]->id),'Storefront '.$type.' filter includes admin-created attribute');
$data['name']=$tag.' updated';$data['variants'][0]['stock']=2;$controller->save(req('/admin/products/'.$product->id,$data),$library,$product);check($product->fresh()->name===$data['name'] && $product->variants()->first()->stock===2,'Admin product edit updates variant stock');
$reviewController=new App\Http\Controllers\CustomerReviewController;$reviewController->save(req('/admin/customer-reviews',['name'=>$tag,'star'=>5,'description'=>'Audit review','status'=>true]),$library);$review=App\Models\CustomerReview::where('name',$tag)->firstOrFail();check($review->star===5 || (int)$review->star===5,'Admin review creation succeeds');$reviewController->destroy(req('/admin/customer-reviews/'.$review->id),$review,$library);check(!App\Models\CustomerReview::whereKey($review->id)->exists(),'Admin review delete succeeds');
$contactController=new App\Http\Controllers\ContactController;$contactController->store(req('/contact',['name'=>$tag,'phone_number'=>'01700000000','subject'=>'Audit contact','description'=>'Temporary message']));check(App\Models\Contact::where('name',$tag)->exists(),'Contact form saves an admin-visible message');
}finally{DB::rollBack();}
